    import {
      forwardRef, 
      useRef, 
      useImperativeHandle
    } from 'react';

    const MyInput = forwardRef((props, ref) => {
      const realInputRef = useRef(null);
      useImperativeHandle(ref, () => ({
        // Only expose focus and nothing else
        focus() {
          realInputRef.current.focus();
        },
      }));
      return <input {...props} ref={realInputRef} />;
    });

    export default function Form() {
      const inputRef = useRef(null);

      function handleClick() {
        inputRef.current.focus();
      }

      return (
        <>
          <MyInput ref={inputRef} />
          <button onClick={handleClick}>
            Focus the input
          </button>
        </>
      );
    }



Show more

Here, ` realInputRef ` inside ` MyInput ` holds the actual input DOM node.
However, ` useImperativeHandle ` instructs React to provide your own special
object as the value of a ref to the parent component. So ` inputRef.current `
inside the ` Form ` component will only have the ` focus ` method. In this
case, the ref “handle” is not the DOM node, but the custom object you create
inside ` useImperativeHandle ` call.

