](/mwiki/index.php?title=cpp/ranges/slide_view&action=edit&section=7 "Edit
section: Example") ]  Example

Run this code



    #include <algorithm>
    #include <iostream>
    #include <ranges>
     
    auto print_subrange = [](std::[ranges::viewable_range](http://en.cppreference.com/w/cpp/ranges/viewable_range) auto&& r)
    {
        [std::cout](http://en.cppreference.com/w/cpp/io/cout) << '[';
        for (char space[]{0,0}; auto elem : r)
            [std::cout](http://en.cppreference.com/w/cpp/io/cout) << space << elem, *space = ' ';
        [std::cout](http://en.cppreference.com/w/cpp/io/cout) << "] ";
    };
     
    int main()
    {
        const auto v = {1, 2, 3, 4, 5, 6};
     
        [std::cout](http://en.cppreference.com/w/cpp/io/cout) << "All sliding windows of width:\n";
        for (const unsigned width : std::[views::iota](http://en.cppreference.com/w/cpp/ranges/iota_view)(1U, 1U + v.size()))
        {
            auto const windows = v | std::views::slide(width);
            [std::cout](http://en.cppreference.com/w/cpp/io/cout) << "W = " << width << ": ";
            std::[ranges::for_each](http://en.cppreference.com/w/cpp/algorithm/ranges/for_each)(windows, print_subrange);
            [std::cout](http://en.cppreference.com/w/cpp/io/cout) << '\n';
        }
    }

