###  Inline error handling example  ​

When handling errors inline after [ ` unwrapping `
](/api/createAsyncThunk#unwrapping-result-actions) a mutation call, a thrown
error will have a type of ` any ` for typescript versions below 4.4, or [ `
unknown ` for versions 4.4+
](https://devblogs.microsoft.com/typescript/announcing-typescript-4-4/#use-
unknown-catch-variables) . In order to safely access properties of the error,
you must first narrow the type to a known type. This can be done using a [
type predicate
](https://www.typescriptlang.org/docs/handbook/2/narrowing.html#using-type-
predicates) as shown below.

services/helpers.ts



    import { FetchBaseQueryError } from '@reduxjs/toolkit/query'  

    /**  
     * Type predicate to narrow an unknown error to `FetchBaseQueryError`  
     */  
    export function isFetchBaseQueryError(  
      error: unknown,  
    ): error is FetchBaseQueryError {  
      return typeof error === 'object' && error != null && 'status' in error  
    }  

    /**  
     * Type predicate to narrow an unknown error to an object with a string 'message' property  
     */  
    export function isErrorWithMessage(  
      error: unknown,  
    ): error is { message: string } {  
      return (  
        typeof error === 'object' &&  
        error != null &&  
        'message' in error &&  
        typeof (error as any).message === 'string'  
      )  
    }  


